import type { Language, LocalNames } from '../i18n';
import type { Coordinate } from '../types';
import generated from './generated/world-rivers.json';

// River geometry is generated by scripts/prepare-map.mjs from Natural Earth v5.1.2 ne_50m_rivers_lake_centerlines_scale_rank (public domain).
// Rendering only: rivers never affect the simulation.
export interface River {
  /** Natural Earth name, or the English override below. */
  name: string;
  nameKo?: string;
  /** Natural Earth ja / zh-CN / zh-TW names, only the ones the source has. */
  names?: LocalNames;
  /** 1 = the great rivers ... 6 = minor rivers; decides from which zoom the river is drawn (see `riverTier`). */
  scalerank: number;
  /** Polylines in lon/lat; none crosses the antimeridian. */
  lines: Coordinate[][];
}

// Natural Earth names that read badly as map labels, keyed by the name in the generated file (a transliterated source name, or a Korean name that is wrong).
export const OVERRIDES: Record<string, { name?: string; nameKo?: string; names?: LocalNames }> = {
  'Chang Jiang': { name: 'Yangtze', nameKo: '장강' },
  Huang: { name: 'Yellow River' },
  Amazonas: { name: 'Amazon' },
  Lancang: { name: 'Mekong' },
  'Heilong Jiang': { name: 'Amur' },
  Dihang: { name: 'Brahmaputra' },
  Ayeyarwady: { name: 'Irrawaddy' },
  Firat: { name: 'Euphrates' },
  'El Bahr el Azraq': { name: 'Blue Nile' },
  // Natural Earth gives the Chinese Han River the Korean name of the Han River in Seoul.
  Han: { name: 'Han Shui', nameKo: '한수이', names: { ja: '漢水', 'zh-CN': '汉水', 'zh-TW': '漢水' } },
};

/** Rivers, the great ones (lowest scalerank) first. */
export const RIVERS: River[] = (generated.rivers as River[]).map(river => ({ ...river, ...OVERRIDES[river.name] }));

export const riverName = (r: River, lang: Language): string => (lang === 'en' ? r.name : (lang === 'ko' ? r.nameKo : r.names?.[lang]) || r.name);
